// original.cs — five endpoints, and every one starts with the same three
// copy-pasted blocks: log the request, check the API key, time the handler.
// Fifteen pasted blocks (well... fourteen: one endpoint FORGOT the auth
// check — find the ⚠️). The real work of each endpoint is one line, buried.
//
// Run:   dotnet run csharp/19-middleware-pipeline/original.cs
// Then:  curl http://localhost:5019/status
//        curl -H "X-Api-Key: letmein" http://localhost:5019/admin/stats

using System.Diagnostics;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// ---- public endpoints -----------------------------------------------------

app.MapGet("/status", (HttpContext ctx) =>
{
    Console.WriteLine($"--> GET /status");                                  // logging, copy #1
    var sw = Stopwatch.StartNew();                                          // timing, copy #1
    var result = new { status = "ok" };                                     // the real work
    Console.WriteLine($"<-- 200 GET /status ({sw.ElapsedMilliseconds}ms)");
    return Results.Json(result);
});

app.MapGet("/time", (HttpContext ctx) =>
{
    Console.WriteLine($"--> GET /time");                                    // logging, copy #2
    var sw = Stopwatch.StartNew();                                          // timing, copy #2
    var result = new { time = DateTime.Now.ToString("HH:mm:ss") };          // the real work
    // ...whoever pasted this one forgot the closing log line. Copies drift.
    return Results.Json(result);
});

// ---- admin endpoints (API key required... in theory) -----------------------

app.MapGet("/admin/stats", (HttpContext ctx) =>
{
    Console.WriteLine($"--> GET /admin/stats");                             // logging, copy #3
    var sw = Stopwatch.StartNew();                                          // timing, copy #3
    string? key = ctx.Request.Headers["X-Api-Key"];                         // auth, copy #1
    if (key != "letmein")
    {
        Console.WriteLine($"<-- 401 GET /admin/stats ({sw.ElapsedMilliseconds}ms)");
        return Results.Json(new { error = "wrong key" }, statusCode: 401);
    }
    var result = new { quotes = 3, uptimeHours = 12 };                      // the real work
    Console.WriteLine($"<-- 200 GET /admin/stats ({sw.ElapsedMilliseconds}ms)");
    return Results.Json(result);
});

// ⚠️ THE BUG: whoever added this endpoint copy-pasted from /time (a public
// endpoint) instead of /admin/stats — so the auth block never got pasted in.
// /admin/users is wide open to anyone, and NOTHING in the code complains.
// This is not a hypothetical: "forgot to paste the check" is how real
// security holes are born. Copy-paste has no safety net.
app.MapGet("/admin/users", (HttpContext ctx) =>
{
    Console.WriteLine($"--> GET /admin/users");                             // logging, copy #4
    var sw = Stopwatch.StartNew();                                          // timing, copy #4
    var result = new[] { new { name = "ada" }, new { name = "linus" } };    // the real work
    Console.WriteLine($"<-- 200 GET /admin/users ({sw.ElapsedMilliseconds}ms)");
    return Results.Json(result);
});

app.MapPost("/admin/reset", (HttpContext ctx) =>
{
    Console.WriteLine($"--> POST /admin/reset");                            // logging, copy #5
    var sw = Stopwatch.StartNew();                                          // timing, copy #5
    string? key = ctx.Request.Headers["X-Api-Key"];                         // auth, copy #2
    if (key != "letmein")
    {
        Console.WriteLine($"<-- 401 POST /admin/reset ({sw.ElapsedMilliseconds}ms)");
        // note: a DIFFERENT 401 body than /admin/stats — the copies drifted
        return Results.Json(new { denied = true }, statusCode: 401);
    }
    var result = new { reset = true };                                      // the real work
    Console.WriteLine($"<-- 200 POST /admin/reset ({sw.ElapsedMilliseconds}ms)");
    return Results.Json(result);
});

app.Run("http://localhost:5019");

# 🏋️ Practice: Middleware Pipeline

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. Stamp every response with an API version (warm-up)

Add a station that puts `X-Api-Version: 1.0` on *every* response — 200s, 401s, all of them. One
`app.Use` block; zero endpoint edits.
*Practices:* your first from-scratch station + choosing where in the order it goes.
**Hint:** setting a header *before* `await next(ctx)` is safe — the envelope isn't sealed yet.
**Check offline:** `curl -i http://localhost:5019/status` and `curl -i http://localhost:5019/admin/stats`
(no key) → both carry `X-Api-Version: 1.0`, the second alongside its 401.

### ⭐⭐ 2. A read-only API key (core)

Add a second key, `lookdonttouch`, that may pass the admin gate **only for GET requests** — it can
read `/admin/stats` but a `POST /admin/reset` with it stays 401. Put the decision in a new pure
`ApiKeyChecker.CanAccess(string? presented, string method)` and make the gate call it; `IsValid` and
its tests stay untouched.
*Practices:* extending a pure decision class + one-line middleware change; the domain layer without HTTP.
**Hint:** compare the method with `string.Equals(method, "GET", StringComparison.OrdinalIgnoreCase)` —
never `==`, header casing isn't guaranteed.
**Check offline:** add this Check test — it should pass:
`Check.True(!ApiKeyChecker.CanAccess("lookdonttouch", "POST"), "read-only key cannot POST");`
then `curl -i -H "X-Api-Key: lookdonttouch" http://localhost:5019/admin/stats` → `200`, and the same
header on `-X POST .../admin/reset` → `401`.

### ⭐⭐ 3. Turn away suspicious paths (core)

Add a station — outermost, before logging — that answers `400 {"error":"suspicious path"}` for any
path containing `..`, `//`, or a backslash, so path-traversal probes never reach a handler. Decision
in `PathRules.IsSuspicious(string? path)`, fully unit-tested.
*Practices:* a short-circuiting security station + pure predicate tests.
**Hint:** the middleware body is the gate's five-line shape: check → status + `WriteAsJsonAsync` + `return`, or `next`.
**Check offline:** `Check.True(PathRules.IsSuspicious("/admin/../secret"), "dot-dot is refused")` passes;
`curl -i "http://localhost:5019/status//x"` → `400`.

### ⭐⭐ 4. Flag slow requests in the log (core)

Extend the timing station: after `await next(ctx)`, if the request took 500 ms or more, print
`SLOW <method> <path> took <elapsed>`. Decide "is this slow?" in a pure
`TimingFormat.IsSlow(TimeSpan, double thresholdMs = 500)`. Add a `GET /slow` endpoint that
`await Task.Delay(600)`s so you can watch it fire.
*Practices:* on-the-way-out middleware work — code after `next` is the response half of the onion.
**Hint:** the stopwatch you already have keeps ticking; read `sw.Elapsed` after `next` returns.
**Check offline:** `Check.True(!TimingFormat.IsSlow(TimeSpan.FromMilliseconds(499)), "499ms is fine")`
passes; `curl http://localhost:5019/slow` → server console prints the SLOW line, `/status` doesn't.

### ⭐⭐⭐ 5. Correlation ids (challenge)

Every response should carry `X-Request-Id`, and both log lines (`-->` and `<--`) should include it so
you can match arrivals to departures in a busy log. If the *client* sent an `X-Request-Id` that is
sane (non-blank, ≤ 32 chars, only letters/digits/dashes), reuse it — that's how services chain traces
— otherwise mint a fresh short id. Sanity lives in a pure `RequestId.Normalize(string? incoming)`.
*Practices:* one station coordinating request-in, response-out, and logging; a pure normalize rule.
**Hint:** `Guid.NewGuid().ToString("N")[..12]` mints 12 hex chars; stamp the header via `OnStarting`.
**Check offline:** add this Check test — it should pass:
`Check.Equal("abc-123", RequestId.Normalize("abc-123"), "a sane client id survives");`
then `curl -i -H "X-Request-Id: trace-42" http://localhost:5019/status` → response header
`X-Request-Id: trace-42` and both console lines tagged `[trace-42]`.

## Solutions

### 1. Version header

```csharp
// Program.cs — first station, right after `var app = builder.Build();`
app.Use(async (ctx, next) =>
{
    ctx.Response.Headers["X-Api-Version"] = "1.0";
    await next(ctx);
});
```

WHY: headers may be set any time before the response starts streaming, so writing it on the way *in*
is the simplest correct move — no `OnStarting` needed because nothing has to be computed at the end
(contrast `X-Elapsed`). Outermost placement means even the gate's 401s pass through it already stamped.

### 2. Read-only key

```csharp
// PipelineParts.cs — ApiKeyChecker grows; IsValid stays for the old tests
private const string ReadOnlyKey = "lookdonttouch";

/// Admin key: everything. Read-only key: GET only. Anything else: nothing.
public static bool CanAccess(string? presented, string method) =>
    presented == Secret
    || (presented == ReadOnlyKey && string.Equals(method, "GET", StringComparison.OrdinalIgnoreCase));

// Program.cs — the gate's condition changes, nothing else does
if (!ApiKeyChecker.CanAccess(ctx.Request.Headers[ApiKeyChecker.HeaderName], ctx.Request.Method))

// Tests.cs
Check.True(ApiKeyChecker.CanAccess("letmein", "POST"), "admin key can do anything");
Check.True(ApiKeyChecker.CanAccess("lookdonttouch", "GET"), "read-only key can GET");
Check.True(ApiKeyChecker.CanAccess("lookdonttouch", "get"), "method casing doesn't matter");
Check.True(!ApiKeyChecker.CanAccess("lookdonttouch", "POST"), "read-only key cannot POST");
Check.True(!ApiKeyChecker.CanAccess(null, "GET"), "no key is still no key");
```

WHY: "who may do what" is policy, so it lands in the pure class where five one-line tests pin down
every combination — the middleware stays a dumb applier. GET-only is the *safe method* idea from
cs#16 turned into an authorization tier; case-insensitive method comparison avoids a trap that would
only surface with certain clients.

### 3. Suspicious paths

```csharp
// PipelineParts.cs — PathRules grows
/// Path-traversal and double-slash probes: refuse before any handler runs.
public static bool IsSuspicious(string? path) =>
    path is not null && (path.Contains("..") || path.Contains("//") || path.Contains('\\'));

// Program.cs — OUTERMOST station (even before logging, or right after it — decide and say why)
app.Use(async (ctx, next) =>
{
    if (PathRules.IsSuspicious(ctx.Request.Path))
    {
        ctx.Response.StatusCode = 400;
        await ctx.Response.WriteAsJsonAsync(new { error = "suspicious path" });
        return;   // short-circuit: nothing inside ever sees this request
    }
    await next(ctx);
});
```

WHY: refusing garbage at the outermost ring is defense-in-depth — the fewer stations a hostile
request touches, the less can go wrong. `ctx.Request.Path` converts to `string?` implicitly, so the
pure predicate needs no ASP.NET types, which is exactly what keeps it testable in one line each.

### 4. Slow-request flag

```csharp
// PipelineParts.cs — TimingFormat grows
public static bool IsSlow(TimeSpan elapsed, double thresholdMs = 500) =>
    elapsed.TotalMilliseconds >= thresholdMs;

// Program.cs — the timing station gains an after-next tail
app.Use(async (ctx, next) =>
{
    var sw = Stopwatch.StartNew();
    ctx.Response.OnStarting(() =>
    {
        ctx.Response.Headers["X-Elapsed"] = TimingFormat.Header(sw.Elapsed);
        return Task.CompletedTask;
    });
    await next(ctx);
    if (TimingFormat.IsSlow(sw.Elapsed))
        Console.WriteLine($"SLOW {ctx.Request.Method} {ctx.Request.Path} took {TimingFormat.Header(sw.Elapsed)}");
});

// Program.cs — something to catch
app.MapGet("/slow", async () => { await Task.Delay(600); return new { slow = true }; });
```

WHY: the header must be decided *before* the body ships (`OnStarting`), but a console line has no such
deadline — code after `await next` is the natural place for anything that reacts to how the request
went. The threshold hides behind a pure function so "what counts as slow" is a tested number, not a
magic literal buried in plumbing.

### 5. Correlation ids

```csharp
// PipelineParts.cs — new pure class
public static class RequestId
{
    /// Keep the caller's id when it is sane; otherwise mint a fresh short one.
    public static string Normalize(string? incoming) =>
        !string.IsNullOrWhiteSpace(incoming)
        && incoming.Length <= 32
        && incoming.All(c => char.IsAsciiLetterOrDigit(c) || c == '-')
            ? incoming
            : Guid.NewGuid().ToString("N")[..12];
}

// Program.cs — REPLACES the logging station (station 1)
app.Use(async (ctx, next) =>
{
    var id = RequestId.Normalize(ctx.Request.Headers["X-Request-Id"]);
    ctx.Response.OnStarting(() =>
    {
        ctx.Response.Headers["X-Request-Id"] = id;
        return Task.CompletedTask;
    });
    Console.WriteLine($"--> [{id}] {ctx.Request.Method} {ctx.Request.Path}");
    await next(ctx);
    Console.WriteLine($"<-- [{id}] {ctx.Response.StatusCode} {ctx.Request.Method} {ctx.Request.Path}");
});

// Tests.cs
Check.Equal("abc-123", RequestId.Normalize("abc-123"), "a sane client id survives");
Check.Equal(12, RequestId.Normalize(null).Length, "a missing id is minted at 12 chars");
Check.True(RequestId.Normalize("bad id!") != "bad id!", "spaces/punctuation get replaced");
Check.True(RequestId.Normalize(new string('x', 33)).Length == 12, "over-long ids get replaced");
```

WHY: the id is *born* on the way in, *logged* on both passes, and *stamped* on the way out — one
station owning one concern across both directions, which is the whole middleware mental model in a
single block. Validating client-supplied ids matters because headers are attacker-controlled input:
`Normalize` means a hostile value can garble at most itself, never your log format. The local `var id`
is captured by both the `OnStarting` callback and the departure log line, so all three uses agree.

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

// The DECISIONS the middleware make, extracted as pure static methods.
// Middleware plumbing (HttpContext, headers, next()) is hard to unit-test;
// these one-liners are trivial to test — so the pipeline stays thin and
// the logic stays covered. Same split as always: decide here, do there.

public static class ApiKeyChecker
{
    public const string HeaderName = "X-Api-Key";

    // The one accepted key. Hard-coded for the lesson; a real app reads
    // secrets from configuration (that's cs#22) — never from source code.
    private const string Secret = "letmein";

    /// Exact, case-sensitive match; null/blank never passes.
    public static bool IsValid(string? presented) => presented == Secret;
}

public static class PathRules
{
    /// Which paths are protected: /admin itself and anything under it —
    /// but NOT /administrator (prefix matching needs the slash check!).
    public static bool IsAdmin(string? path)
    {
        if (string.IsNullOrEmpty(path)) return false;
        var p = path.ToLowerInvariant();
        return p == "/admin" || p.StartsWith("/admin/");
    }
}

public static class TimingFormat
{
    /// "12.3ms" — one decimal, invariant culture so a German locale
    /// doesn't turn it into "12,3ms" and confuse every client parser.
    public static string Header(TimeSpan elapsed) =>
        elapsed.TotalMilliseconds.ToString("0.0", System.Globalization.CultureInfo.InvariantCulture) + "ms";
}

// Program.cs — the three copy-pasted concerns became three middleware
// STATIONS, written once, in order. Requests flow DOWN through them into
// the endpoint; responses flow back UP. Endpoints keep only their real work.
//
// ORDER MATTERS: logging is outermost (sees everything, even 401s),
// timing next (measures everything inside it), the auth gate innermost
// (and only on /admin paths). Swap them and the meaning changes — e.g.
// auth outside logging would make rejected requests invisible in the log.

using System.Diagnostics;

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// STATION 1 — request logging (was: pasted 5 times, one copy half-missing).
app.Use(async (ctx, next) =>
{
    Console.WriteLine($"--> {ctx.Request.Method} {ctx.Request.Path}");
    await next(ctx);
    Console.WriteLine($"<-- {ctx.Response.StatusCode} {ctx.Request.Method} {ctx.Request.Path}");
});

// STATION 2 — timing (was: pasted 5 times). Response headers must be
// decided before the body starts streaming — like addressing an envelope
// before mailing it — so we register an OnStarting callback that stamps
// the header at the last possible moment.
app.Use(async (ctx, next) =>
{
    var sw = Stopwatch.StartNew();
    ctx.Response.OnStarting(() =>
    {
        ctx.Response.Headers["X-Elapsed"] = TimingFormat.Header(sw.Elapsed);
        return Task.CompletedTask;
    });
    await next(ctx);
});

// STATION 3 — the API-key gate, ONLY for /admin paths (UseWhen = a branch
// in the assembly line). Every /admin endpoint is protected — including
// ones nobody has written yet. The original's forgot-to-paste bug is now
// structurally impossible.
app.UseWhen(
    ctx => PathRules.IsAdmin(ctx.Request.Path),
    admin => admin.Use(async (ctx, next) =>
    {
        if (!ApiKeyChecker.IsValid(ctx.Request.Headers[ApiKeyChecker.HeaderName]))
        {
            ctx.Response.StatusCode = 401;
            await ctx.Response.WriteAsJsonAsync(new { error = "missing or wrong X-Api-Key header" });
            return;   // short-circuit: the endpoint never runs
        }
        await next(ctx);
    }));

// The endpoints — nothing left but the real work (one line each, as it
// always secretly was).
app.MapGet("/status", () => new { status = "ok" });
app.MapGet("/time", () => new { time = DateTime.Now.ToString("HH:mm:ss") });
app.MapGet("/admin/stats", () => new { quotes = 3, uptimeHours = 12 });
app.MapGet("/admin/users", () => new[] { new { name = "ada" }, new { name = "linus" } });
app.MapPost("/admin/reset", () => new { reset = true });

app.Run("http://localhost:5019");

// Tests.cs — the pipeline's DECISIONS, tested without any pipeline.
// Who may pass? Which paths are protected? What does the timing header
// look like? All pure functions now — the middleware just applies them.
public static class Tests
{
    public static int Run()
    {
        Console.WriteLine("ApiKeyChecker — who gets through the gate");
        Check.True(ApiKeyChecker.IsValid("letmein"), "the right key is accepted");
        Check.True(!ApiKeyChecker.IsValid("password123"), "a wrong key is rejected");
        Check.True(!ApiKeyChecker.IsValid("LETMEIN"), "keys are case-sensitive");
        Check.True(!ApiKeyChecker.IsValid(" letmein"), "no sloppy whitespace allowed");
        Check.True(!ApiKeyChecker.IsValid(""), "an empty header value is rejected");
        Check.True(!ApiKeyChecker.IsValid(null), "a missing header (null) is rejected");

        Console.WriteLine("PathRules.IsAdmin — which doors the gate guards");
        Check.True(PathRules.IsAdmin("/admin"), "/admin itself is protected");
        Check.True(PathRules.IsAdmin("/admin/stats"), "/admin/stats is protected");
        Check.True(PathRules.IsAdmin("/admin/users"), "/admin/users is protected — the original's forgotten endpoint, covered by construction");
        Check.True(PathRules.IsAdmin("/admin/"), "/admin/ (trailing slash) is protected");
        Check.True(PathRules.IsAdmin("/ADMIN/stats"), "matching ignores case (URLs arrive in any casing)");
        Check.True(!PathRules.IsAdmin("/status"), "/status is public");
        Check.True(!PathRules.IsAdmin("/administrator"), "/administrator is NOT under /admin — naive StartsWith would wrongly lock this");
        Check.True(!PathRules.IsAdmin("/adminlike"), "/adminlike is not under /admin either");
        Check.True(!PathRules.IsAdmin(""), "an empty path is not admin");
        Check.True(!PathRules.IsAdmin(null), "a null path is not admin");

        Console.WriteLine("TimingFormat.Header — what goes into X-Elapsed");
        Check.Equal("12.3ms", TimingFormat.Header(TimeSpan.FromMilliseconds(12.34)), "rounds to one decimal");
        Check.Equal("0.0ms", TimingFormat.Header(TimeSpan.Zero), "zero elapsed formats cleanly");
        Check.Equal("1000.0ms", TimingFormat.Header(TimeSpan.FromSeconds(1)), "a full second is still expressed in ms");
        Check.Equal("0.5ms", TimingFormat.Header(TimeSpan.FromMilliseconds(0.51)), "sub-millisecond values survive");

        return Check.Summary();
    }
}
